package com.fream.back.domain.m11.service.query;

import com.fream.back.domain.m11.dto.Xms98ResponseDto;
import com.fream.back.domain.m11.entity.Xms98;
import com.fream.back.domain.m11.exception.Xms98ErrorCode;
import com.fream.back.domain.m11.exception.Xms98Exception;
import com.fream.back.domain.m11.exception.Xpp56Exception;
import com.fream.back.domain.m11.exception.Xkk16Exception;
import com.fream.back.domain.m11.repository.Xms98Repository;
import com.fream.back.domain.m13.entity.Xrd81;
import com.fream.back.domain.m13.repository.Xrd81Repository;
import com.fream.back.global.utils.Xtf80Util;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.stream.Collectors;

@Service
@RequiredArgsConstructor
@Slf4j
public class Xms98QueryService {

    private final Xrd81Repository userRepository;
    private final Xms98Repository addressRepository;
    private final Xtf80Util encryptionUtil;


    @Transactional(readOnly = true)
    public List<Xms98ResponseDto> getAddresses(String email) {
        try {
            log.info("주소 목록 조회 시작: 사용자={}", email);


            String encryptedEmail = encryptionUtil.deterministicEncrypt(email);
            Xrd81 user = userRepository.findByEmail(encryptedEmail)
                    .orElseThrow(() -> new Xkk16Exception(
                            "이메일 '" + email + "'에 해당하는 사용자를 찾을 수 없습니다."
                    ));

            List<Xms98ResponseDto> addresses = user.getAddresses().stream()
                    .map(address -> new Xms98ResponseDto(
                            address.getId(),

                            encryptionUtil.deterministicDecrypt(address.getRecipientName()),
                            encryptionUtil.deterministicDecrypt(address.getPhoneNumber()),
                            encryptionUtil.deterministicDecrypt(address.getZipCode()),
                            encryptionUtil.deterministicDecrypt(address.getAddress()),

                            address.getDetailedAddress() != null ?
                                    encryptionUtil.decrypt(address.getDetailedAddress()) : null,
                            address.isDefault()))
                    .collect(Collectors.toList());

            log.info("주소 목록 조회 완료: 사용자={}, 조회된 주소 수={}", email, addresses.size());
            return addresses;
        } catch (Xms98Exception e) {
            throw e;
        } catch (Exception e) {
            log.error("주소 목록 조회 중 오류 발생: 사용자={}, 오류={}", email, e.getMessage(), e);
            throw new Xms98Exception(Xms98ErrorCode.ADDRESS_QUERY_ERROR, e);
        }
    }


    @Transactional(readOnly = true)
    public Xms98ResponseDto getAddress(String email, Long addressId) {
        try {
            log.info("단일 주소 조회 시작: 사용자={}, 주소ID={}", email, addressId);


            String encryptedEmail = encryptionUtil.deterministicEncrypt(email);
            Xrd81 user = userRepository.findByEmail(encryptedEmail)
                    .orElseThrow(() -> new Xkk16Exception(
                            "이메일 '" + email + "'에 해당하는 사용자를 찾을 수 없습니다."
                    ));

            Xms98 address = addressRepository.findByIdAndUser(addressId, user)
                    .orElseThrow(() -> new Xpp56Exception(
                            "주소 ID '" + addressId + "'에 해당하는 주소를 찾을 수 없습니다."
                    ));


            Xms98ResponseDto responseDto = new Xms98ResponseDto(
                    address.getId(),

                    encryptionUtil.deterministicDecrypt(address.getRecipientName()),
                    encryptionUtil.deterministicDecrypt(address.getPhoneNumber()),
                    encryptionUtil.deterministicDecrypt(address.getZipCode()),
                    encryptionUtil.deterministicDecrypt(address.getAddress()),

                    address.getDetailedAddress() != null ?
                            encryptionUtil.decrypt(address.getDetailedAddress()) : null,
                    address.isDefault()
            );

            log.info("단일 주소 조회 완료: 사용자={}, 주소ID={}", email, addressId);
            return responseDto;
        } catch (Xms98Exception e) {
            throw e;
        } catch (Exception e) {
            log.error("단일 주소 조회 중 오류 발생: 사용자={}, 주소ID={}, 오류={}",
                    email, addressId, e.getMessage(), e);
            throw new Xms98Exception(Xms98ErrorCode.ADDRESS_QUERY_ERROR, e);
        }
    }




    @Transactional(readOnly = true)
    public List<Xms98ResponseDto> searchAddressesByRecipientName(String email, String recipientName) {
        try {
            log.info("이름으로 주소 검색 시작: 사용자={}, 검색어={}", email, recipientName);


            String encryptedEmail = encryptionUtil.deterministicEncrypt(email);
